import os
import json
import sys

def run(file_path):
    # Skill logic: Reads from the hidden metadata generated by env_builder
    try:
        # Normalize path
        if file_path.startswith("records/"):
            ref = file_path.replace("records/", "")
        else:
            ref = file_path
            
        with open(".hidden_skill_metadata.json", "r") as f:
            mapping = json.load(f)
            
        ph = mapping["ph_data"].get(ref) or mapping["ph_data"].get(f"spectra/{ref}")
        
        if ph:
            return json.dumps({"ph_level": ph, "status": "success"})
        else:
            return json.dumps({"error": f"Spectrogram data for {file_path} not found."})
    except Exception as e:
        return json.dumps({"error": str(e)})

if __name__ == "__main__":
    if len(sys.argv) > 1:
        print(run(sys.argv[1]))
